(()=>{'use strict';const cards=[...document.querySelectorAll('[data-prebuilt-id]')];if(!cards.length)return;
 let region='CA',systems=[],selected=new Set();try{region=new URLSearchParams(location.search).get('region')||localStorage.getItem('pcp-region')||'CA';const saved=JSON.parse(localStorage.getItem('pcp-prebuilt-shortlist')||'[]');if(Array.isArray(saved))selected=new Set(saved.filter(id=>typeof id==='string').slice(0,3))}catch{}if(!['CA','US'].includes(region))region='CA';
 let visibleLimit=12;const brand=document.querySelector('#prebuilt-brand'),more=document.querySelector('[data-prebuilt-more]');const query=document.querySelector('#prebuilt-search'),gpu=document.querySelector('#prebuilt-gpu'),status=document.querySelector('[data-prebuilt-status]'),compareButton=document.querySelector('[data-prebuilt-open-compare]'),comparison=document.querySelector('[data-prebuilt-comparison]');
 const text=(parent,value,tag='td')=>{const el=document.createElement(tag);el.textContent=value??'Not verified';parent.append(el);return el};
 function render(){let count=0;for(const card of cards){const matches=card.dataset.prebuiltRegion===region&&(!brand.value||card.dataset.brand===brand.value)&&card.dataset.name.includes(query.value.trim().toLowerCase())&&(!gpu.value||card.dataset.gpu===gpu.value);card.hidden=!matches||count>=visibleLimit;if(matches)count++;card.querySelector('input').checked=selected.has(card.dataset.prebuiltId)}document.querySelector('[data-prebuilt-count]').textContent=count;document.querySelector('[data-prebuilt-region]').textContent=region==='CA'?'Canada · CAD':'United States · USD';document.querySelector('[data-prebuilt-empty]').hidden=count>0;more.hidden=count<=visibleLimit;more.textContent="Show more systems ("+Math.max(0,count-visibleLimit)+")";compareButton.disabled=selected.size<2;compareButton.textContent='Compare selected'+(selected.size?' ('+selected.size+')':'');comparison.hidden=true}
 function showComparison(){const pair=systems.filter(s=>selected.has(s.id));if(pair.length<2)return;const table=document.createElement('table'),head=document.createElement('thead'),tr=document.createElement('tr');for(const label of ['System',...pair.map(p=>p.name)]){const th=text(tr,label,'th');th.scope='col'}head.append(tr);table.append(head);const body=document.createElement('tbody');for(const [key,label]of [['region','Country'],['cpu','Processor'],['gpu','Graphics card'],['ram','Memory'],['ramLayout','Memory layout'],['storage','Storage'],['board','Motherboard'],['psu','Power supply'],['seller','Seller'],['warranty','Warranty']]){const row=document.createElement('tr');const th=text(row,label,'th');th.scope='row';pair.forEach(p=>text(row,p[key]));body.append(row)}table.append(body);comparison.replaceChildren(table);comparison.hidden=false;comparison.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
 const refilter=()=>{visibleLimit=12;render();};more.addEventListener('click',()=>{visibleLimit+=12;render();});brand.addEventListener('change',refilter);query.addEventListener('input',refilter);gpu.addEventListener('change',refilter);document.querySelector('[data-prebuilt-reset]').addEventListener('click',()=>{query.value='';gpu.value='';brand.value='';visibleLimit=12;render()});
 for(const checkbox of document.querySelectorAll('[data-prebuilt-compare]'))checkbox.addEventListener('change',()=>{if(checkbox.checked&&selected.size>=3){checkbox.checked=false;status.textContent='Compare up to three systems at a time.';return}checkbox.checked?selected.add(checkbox.dataset.prebuiltCompare):selected.delete(checkbox.dataset.prebuiltCompare);status.textContent='';render()});
 document.querySelectorAll('.country-switch [data-region]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.region===region)return;quotes[region]=Object.fromEntries(new FormData(worksheet));region=button.dataset.region;selected.clear();visibleLimit=12;restoreQuote();render()}));compareButton.addEventListener('click',showComparison);document.querySelector('[data-prebuilt-save]').addEventListener('click',()=>{try{localStorage.setItem('pcp-prebuilt-shortlist',JSON.stringify([...selected]));status.textContent='Shortlist saved on this device.'}catch{status.textContent='Saving is unavailable. Keep the selected systems open.'}});
 const worksheet=document.querySelector('[data-buy-worksheet]'),result=document.querySelector('[data-buy-result]'),money=n=>new Intl.NumberFormat(region==='CA'?'en-CA':'en-US',{style:'currency',currency:region==='CA'?'CAD':'USD',currencyDisplay:'code'}).format(n);
 function worksheetResult(){const values=Object.fromEntries([...new FormData(worksheet)].map(([k,v])=>[k,String(v).trim()===''?null:Number(v)]));if(Object.values(values).some(v=>v===null||!Number.isFinite(v)||v<0||v>1000000)){result.textContent='Complete every required quote before comparing totals. Use zero only for an actual zero cost.';return}const cents=key=>Math.round(values[key]*100),prebuilt=cents('prebuilt')+cents('prebuiltDelivery'),diy=cents('parts')+cents('os')+cents('support')+cents('delivery');result.textContent='Prebuilt: '+money(prebuilt/100)+' · DIY: '+money(diy/100)+' · Difference: '+money(Math.abs(prebuilt-diy)/100)+(prebuilt===diy?' (same total).':prebuilt<diy?' less for the prebuilt.':' less for DIY.')+' Quotes do not establish equal performance or support.'}
 const quotes={};try{const saved=JSON.parse(localStorage.getItem('pcp-build-vs-buy')||'null');if(saved?.version===2){for(const country of ['CA','US'])if(saved.quotes?.[country]&&typeof saved.quotes[country]==='object')quotes[country]=saved.quotes[country]}else if(['CA','US'].includes(saved?.region))quotes[saved.region]=saved.values||{}}catch{}
 function restoreQuote(){worksheet.reset();for(const input of worksheet.querySelectorAll('input[name]'))input.value=String(quotes[region]?.[input.name]??'');document.querySelector('[data-buy-currency]').textContent=region==='CA'?'Canada · enter all quotes in CAD':'United States · enter all quotes in USD';document.querySelector('[data-buy-save-status]').textContent='';}
 worksheet.addEventListener('submit',e=>{e.preventDefault();worksheetResult()});worksheet.addEventListener('reset',()=>{result.textContent='Enter quotes to compare the complete cost.'});document.querySelector('[data-buy-save]').addEventListener('click',()=>{const s=document.querySelector('[data-buy-save-status]');try{quotes[region]=Object.fromEntries(new FormData(worksheet));localStorage.setItem('pcp-build-vs-buy',JSON.stringify({version:2,quotes}));s.textContent='Worksheet saved on this device.'}catch{s.textContent='Local storage is unavailable.'}});restoreQuote();
 fetch('/data/prebuilts.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{systems=data.systems;selected=new Set([...selected].filter(id=>systems.some(s=>s.id===id)).slice(0,3));render()}).catch(()=>{status.textContent='System comparison data is unavailable. The listings and worksheet remain available.'});render();
})();

(()=>{for(const img of document.querySelectorAll(".prebuilt-photo img"))img.addEventListener("error",()=>{img.hidden=true;const fallback=document.createElement("span");fallback.textContent="View product photos at the retailer";img.parentElement.append(fallback);},{once:true});})();
